import os, json, re

d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
content = open(session_file).read()

# Parse as JSON lines and find user/assistant messages containing grids
lines = content.split('\n')
grids = []

for i, line in enumerate(lines):
    if not line.strip():
        continue

    try:
        obj = json.loads(line)

        # Look for "text" field in content that might contain grids
        def extract_text(obj):
            if isinstance(obj, dict):
                return obj.get('text', '')
            elif isinstance(obj, list):
                return ''.join(extract_text(x) for x in obj)
            return ''

        if 'message' in obj:
            msg = obj['message']
            content_text = extract_text(msg) if 'content' in msg else ''

            # Check if this message has Test input info
            if 'Test input' in content_text and 'Wrong attempts' in content_text:
                # Extract the grid section
                start_idx = content_text.find("Test input (23x28):")
                if start_idx >= 0:
                    section = content_text[start_idx+19:]  # After "Test input (23x28):"

                    # Split into individual lines
                    row_lines = []
                    current = ""
                    for c in section:
                        if c == '\n':
                            row_lines.append(current.strip())
                            current = ""
                        else:
                            current += c
                    if current.strip():
                        row_lines.append(current.strip())

                    # Parse into grid
                    grid = []
                    for rl in row_lines[:25]:  # Take up to 25 rows
                        parts = rl.split()
                        if len(parts) == 28:  # Expected columns
                            try:
                                grid.append([int(x) for x in parts])
                            except ValueError:
                                pass

                    if grid:
                        grids.append((i, grid))

    except json.JSONDecodeError:
        pass

print(f"Found {len(grids)} grid(s)")
for idx, (orig_line_idx, grid) in enumerate(grids[:1]):
    print(f"\n=== Grid from line {orig_line_idx} ===")
    print("Dimensions:", len(grid), "x", len(grid[0]) if grid else 0)
    for r in grid[:5]:
        print(" ", ''.join(map(str, r)))

